  `ComicTitle` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `transcript` varchar(5000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `summary` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `authors` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `code` int DEFAULT NULL,
  `date` datetime NOT NULL,
  `ComicWidth` smallint NOT NULL COMMENT 'pixels',
  `ComicHeight` smallint NOT NULL COMMENT 'pixels',
  `BookID` int DEFAULT NULL,
  `SeriesID` int NOT NULL,
  KEY `id` (`id`),
  KEY `SeriesID` (`SeriesID`),
  KEY `BookID` (`BookID`),
  FULLTEXT KEY `filename` (`Filename`,`ComicTitle`,`authors`)
